class Solution {
    public int[][] minScore(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        Integer[] cells = new Integer[m * n];
        for (int i = 0; i < m * n; i++) cells[i] = i;
        Arrays.sort(cells, (a, b) -> Integer.compare(grid[a / n][a % n], grid[b / n][b % n]));
        int[] rowMax = new int[m], colMax = new int[n];
        int[][] res = new int[m][n];
        for (int id : cells) {
            int r = id / n, c = id % n;
            int v = Math.max(rowMax[r], colMax[c]) + 1;
            res[r][c] = v;
            rowMax[r] = colMax[c] = v;
        }
        return res;
    }
}
